class RandomizedSet {
    vector<int> vals;
    unordered_map<int,int> idx;
public:
    RandomizedSet() {}

    bool insert(int val) {
        if (idx.count(val)) return false;
        idx[val] = (int)vals.size();
        vals.push_back(val);
        return true;
    }

    bool remove(int val) {
        auto it = idx.find(val);
        if (it == idx.end()) return false;
        int i = it->second;
        int last = vals.back();
        vals[i] = last;
        idx[last] = i;
        vals.pop_back();
        idx.erase(it);
        return true;
    }

    int getRandom() {
        return vals[rand() % vals.size()];
    }
};
